mapper.select:
SELECT count(spt.id) as num ,spt.status_code FROM market_config mc INNER JOIN safety_patrol_task spt on (mc.market_tenant = spt.market_tenant)
mc.status = true
and mc.market_tenant = #{query.marketTenant}
and spt.create_time >= #{query.period.begin} and spt.create_time < #{query.period.end}
group by status_code

SELECT count(spt.id) as num ,spt.status_code FROM market_config mc INNER JOIN safety_patrol_task spt on (mc.market_tenant = spt.market_tenant)
mc.status = true and spt.result_code = 'ABNORMAL'
and mc.market_tenant = #{query.marketTenant}
and spt.create_time >= #{query.period.begin} and spt.create_time < #{query.period.end}

SELECT
count(spt.id) as total_num
from
safety_patrol_task spt
left join market_config mc on mc.market_tenant = spt.market_tenant

    mc.status = true

        and spt.status_code in

            #{state}



        and spt.market_tenant = #{query.marketTenant}


        and spt.task_create_time >= #{query.period.begin} and spt.task_create_time < #{query.period.end}

SELECT
spt.*
from
safety_patrol_task spt
left join market_config mc on mc.market_tenant = spt.market_tenant

    mc.status = true

        and spt.status_code = #{status}


        and spt.market_tenant = #{query.marketTenant}


        and spt.create_time >= #{query.period.begin} and spt.create_time < #{query.period.end}


        and spt.task_create_time >= #{query.taskCreatePeriod.begin} and spt.task_create_time < #{query.taskCreatePeriod.end}

SELECT
spt.*
from
safety_patrol_task spt
left join market_config mc on mc.market_tenant = spt.market_tenant

    mc.status = true

        and spt.status_code = #{query.state}


        and spt.market_tenant = #{query.marketTenant}


        and spt.task_create_time >= #{query.period.begin} and spt.task_create_time < #{query.period.end}


        and spt.result_code = #{query.resultCode}


order by spt.task_create_time desc
